package com.deepanshuraj.opspilot.tools;
import com.deepanshuraj.opspilot.domain.*; import com.deepanshuraj.opspilot.rag.*; import java.time.Instant; import java.util.*; import org.springframework.ai.tool.annotation.Tool; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class OpsTools { private final OrderRepository orders; private final WorkflowRunRepository workflows; private final OpsTicketRepository tickets; private final RagRetriever rag; public OpsTools(OrderRepository o,WorkflowRunRepository w,OpsTicketRepository t,RagRetriever r){orders=o;workflows=w;tickets=t;rag=r;}
 @Tool(description="Look up an order") public String lookupOrder(String orderId){return orders.findById(orderId.trim()).map(o->"Order %s | customer=%s | product=%s | region=%s | status=%s | createdAt=%s".formatted(o.getOrderId(),o.getCustomer(),o.getProduct(),o.getRegion(),o.getStatus(),o.getCreatedAt())).orElse("No order found for id "+orderId);}
 @Tool(description="Get the latest workflow status") public String getWorkflowStatus(String orderId){return workflows.findFirstByOrderIdOrderByUpdatedAtDesc(orderId.trim()).map(w->"Workflow for %s | step=%s | state=%s | attempts=%d | reason=%s | updatedAt=%s".formatted(orderId,w.getCurrentStep(),w.getState(),w.getAttempts(),Objects.toString(w.getStuckReason(),"-"),w.getUpdatedAt())).orElse("No workflow run found for order "+orderId);}
 @Tool(description="Retry a stuck or failed workflow") @Transactional public String retryStuckWorkflow(String orderId){WorkflowRun w=workflows.findFirstByOrderIdOrderByUpdatedAtDesc(orderId.trim()).orElse(null);if(w==null)return "No workflow run found for order "+orderId;if(!w.getState().equals("STUCK")&&!w.getState().equals("FAILED"))return "Workflow for "+orderId+" is "+w.getState()+"; nothing to retry.";w.retry();workflows.save(w);return "Re-queued workflow for %s (attempt %d). State is now RETRYING; the '%s' step will re-execute.".formatted(orderId,w.getAttempts(),w.getCurrentStep());}
 @Tool(description="Raise an operations ticket") @Transactional public String raiseTicket(String orderId,String summary){String p=summary!=null&&summary.toLowerCase().contains("sla")?"P1":"P2";OpsTicket t=tickets.save(new OpsTicket(orderId,summary,p,Instant.now()));return "Created ticket #"+t.getId()+" ("+p+") for order "+orderId+".";}
 @Tool(description="List active incidents") public String listRecentIncidents(){List<WorkflowRun> runs=workflows.findByStateInOrderByUpdatedAtDesc(List.of("STUCK","FAILED"));return runs.isEmpty()?"No active incidents.":runs.stream().map(w->"%s: %s at step %s (%s)".formatted(w.getOrderId(),w.getState(),w.getCurrentStep(),Objects.toString(w.getStuckReason(),"-"))).collect(java.util.stream.Collectors.joining("\n"));}
 @Tool(description="Search operational runbooks") public String searchKnowledgeBase(String query){List<RagRetriever.Scored> hits=rag.search(query,3);return hits.isEmpty()?"No matching runbook content.":hits.stream().map(h->"["+h.chunk().source()+"] "+h.chunk().text()).collect(java.util.stream.Collectors.joining("\n---\n"));}}
